 using System.Collections.Concurrent;
 using System.ComponentModel;
 using System.Net;
 using System.Text;
 using System.Text.RegularExpressions;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using OpenAI;

 // --- Configuration ---
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 const string modelId = "gpt-4o-mini-2024-07-18";

 IChatClient chatClient = new OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 // --- Tools ---
 var notebook = new Notebook();
 using var httpClient = new HttpClient();
 httpClient.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");
 httpClient.Timeout = TimeSpan.FromSeconds(15);

 var tools = new AIFunction[]
 {
     AIFunctionFactory.Create(
         [Description("Search the web for information. Returns text snippets from search results.")]
         async (
             [Description("The search query")] string query
         ) =>
         {
             Console.WriteLine($"  🔍 Searching: {query}");
             return await WebSearch.SearchAsync(httpClient, query);
         },
         nameof(WebSearch.SearchAsync),
         "search_web"),

     AIFunctionFactory.Create(
         [Description("Save a research note for later reference.")]
         (
             [Description("Short title for the note")] string title,
             [Description("Detailed content of the note")] string content
         ) =>
         {
             Console.WriteLine($"  📝 Note saved: {title}");
             return notebook.AddNote(title, content);
         },
         nameof(Notebook.AddNote),
         "add_note"),

     AIFunctionFactory.Create(
         [Description("Retrieve all saved research notes.")]
         () =>
         {
             Console.WriteLine("  📋 Reviewing notes...");
             return notebook.GetNotes();
         },
         nameof(Notebook.GetNotes),
         "get_notes"),
 };

 // --- Prompt the user ---
 Console.Write("Enter a research topic: ");
 var topic = Console.ReadLine()?.Trim();
 if (string.IsNullOrEmpty(topic))
 {
     Console.WriteLine("No topic provided. Exiting.");
     return;
 }

 Console.WriteLine($"\n🔬 Researching: {topic}\n");

 var instructions = $"""
     You are a research agent. Your goal is to thoroughly research a topic and produce
     a well-organized summary.

     **Workflow:**
     1. Use `search_web` to find information from multiple angles (try at least 3 queries).
     2. Use `add_note` to save key findings as you discover them.
     3. After gathering enough information, use `get_notes` to review everything.
     4. Produce a final, well-structured summary with sections and key takeaways.

     Be thorough but concise. Cite sources when possible.
     """;

 // --- Build and run the agent ---
 var chatOptions = new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 2048,
     Tools = [.. tools],
 };

 var agent = new ChatClientAgent(
     chatClient,
     instructions: instructions,
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and taking notes.");

 var session = await agent.CreateSessionAsync(
     conversationId: Guid.NewGuid().ToString());

 var runOptions = new ChatClientAgentRunOptions
 {
     ChatOptions = chatOptions,
 };

 await foreach (var update in agent.RunStreamingAsync(
     $"Research the following topic and provide a comprehensive summary: {topic}",
     session,
     runOptions))
 {
     if (!string.IsNullOrEmpty(update.Text))
     {
         Console.Write(update.Text);
     }
 }

 Console.WriteLine();

