 static partial class WebSearch
 {
     public static async Task<string> SearchAsync(HttpClient httpClient, string query)
     {
         try
         {
             var encoded = WebUtility.UrlEncode(query);
             var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
             var html = await httpClient.GetStringAsync(url);
             var text = StripHtml(html);

             const int maxLength = 4000;
             return text.Length > maxLength ? text[..maxLength] : text;
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}";
         }
     }

     private static string StripHtml(string html)
     {
         var text = HtmlTagRegex().Replace(html, " ");
         text = WhitespaceRegex().Replace(text, " ");
         return WebUtility.HtmlDecode(text).Trim();
     }

     [GeneratedRegex("<[^>]+>")]
     private static partial Regex HtmlTagRegex();

     [GeneratedRegex(@"\s+")]
     private static partial Regex WhitespaceRegex();
 }

 sealed class Notebook
 {
     private readonly ConcurrentBag<(string Title, string Content)> _notes = [];

     public string AddNote(string title, string content)
     {
         _notes.Add((title, content));
         return $"Note saved: '{title}'";
     }

     public string GetNotes()
     {
         if (_notes.IsEmpty)
             return "No notes saved yet.";

         var sb = new StringBuilder();
         var i = 1;
         foreach (var (title, content) in _notes)
         {
             sb.AppendLine($"--- Note {i++}: {title} ---");
             sb.AppendLine(content);
             sb.AppendLine();
         }

         return sb.ToString();
     }
 }
